const DEFAULTS = { theme: "light", fontSize: 14, sounds: true };

function readStored(storage) {
  let data;
  try {
    const text = storage.getItem("settings");
    if (text === null) return {};
    data = JSON.parse(text);
  } catch {
    return {};
  }
  if (data === null || typeof data !== "object") return {};
  if (data.version === 1) {
    const out = {};
    if (typeof data.dark === "boolean") out.theme = data.dark ? "dark" : "light";
    if (data.size !== undefined) out.fontSize = Number(data.size);
    return out;
  }
  if (data.version === 2 && data.values && typeof data.values === "object") return data.values;
  return {};
}

function clean(raw) {
  const out = { ...DEFAULTS };
  for (const key of Object.keys(DEFAULTS)) {
    const v = raw[key];
    if (typeof v === typeof DEFAULTS[key] && !(typeof v === "number" && !Number.isFinite(v))) out[key] = v;
  }
  return out;
}

function createSettings(storage) {
  let values = clean(readStored(storage));

  const persist = () => {
    try {
      storage.setItem("settings", JSON.stringify({ version: 2, values }));
      return true;
    } catch {
      return false;
    }
  };

  return {
    get: key => values[key],
    set(key, value) {
      if (!Object.hasOwn(DEFAULTS, key)) throw new Error(`unknown setting ${key}`);
      const type = typeof DEFAULTS[key];
      if (typeof value !== type) throw new TypeError(`${key} must be a ${type}`);
      values = { ...values, [key]: value };
      return persist();
    },
    all: () => ({ ...values }),
    reset() {
      values = { ...DEFAULTS };
      try { storage.removeItem("settings"); } catch { }
    },
  };
}

