function fakeStorage(initial = {}, { full = false, broken = false } = {}) {
  const data = new Map(Object.entries(initial));
  return {
    data,
    getItem(k) { if (broken) throw new Error("blocked"); return data.has(k) ? data.get(k) : null; },
    setItem(k, v) { if (full) throw new Error("QuotaExceededError"); data.set(k, String(v)); },
    removeItem(k) { data.delete(k); },
  };
}

test("defaults and saving", () => {
  const storage = fakeStorage();
  const s = createSettings(storage);
  checkEq(s.all(), { theme: "light", fontSize: 14, sounds: true });
  checkEq(s.set("theme", "dark"), true);
  checkEq(JSON.parse(storage.data.get("settings")), { version: 2, values: { theme: "dark", fontSize: 14, sounds: true } });
  checkEq(createSettings(storage).get("theme"), "dark");
  const copy = s.all();
  copy.theme = "x";
  checkEq(s.get("theme"), "dark");
});

test("bad stored data falls back to defaults", () => {
  checkEq(createSettings(fakeStorage({ settings: "{oops" })).get("fontSize"), 14);
  checkEq(createSettings(fakeStorage({ settings: '{"version": 9, "values": {"theme": "dark"}}' })).get("theme"), "light");
  checkEq(createSettings(fakeStorage({}, { broken: true })).get("sounds"), true);
  checkEq(createSettings(fakeStorage({ settings: "null" })).get("theme"), "light");
  const typed = createSettings(fakeStorage({ settings: '{"version": 2, "values": {"fontSize": "big", "sounds": false, "extra": 1}}' }));
  checkEq(typed.all(), { theme: "light", fontSize: 14, sounds: false });
});

test("migrating version 1", () => {
  checkEq(createSettings(fakeStorage({ settings: '{"version": 1, "dark": true, "size": "16"}' })).all(), { theme: "dark", fontSize: 16, sounds: true });
  checkEq(createSettings(fakeStorage({ settings: '{"version": 1, "dark": false}' })).all(), { theme: "light", fontSize: 14, sounds: true });
  checkEq(createSettings(fakeStorage({ settings: '{"version": 1, "size": "huge"}' })).get("fontSize"), 14);
});

test("checking what is set", () => {
  const s = createSettings(fakeStorage());
  checkThrows(() => s.set("colour", "red"), Error);
  checkThrows(() => s.set("fontSize", "16"), TypeError);
  try { s.set("sounds", "yes"); } catch (e) { checkEq(e.message, "sounds must be a boolean"); }
  try { s.set("toString", 1); } catch (e) { checkEq(e.message, "unknown setting toString"); }
});

test("full storage and reset", () => {
  const storage = fakeStorage({}, { full: true });
  const s = createSettings(storage);
  checkEq(s.set("fontSize", 18), false);
  checkEq(s.get("fontSize"), 18);
  const ok = fakeStorage();
  const t = createSettings(ok);
  t.set("sounds", false);
  t.reset();
  checkEq(t.all(), { theme: "light", fontSize: 14, sounds: true });
  checkEq(ok.data.has("settings"), false);
});

